logger = get_logger(__name__)


class CallScriptLoader:
    async def load(
        self,
        purplefish_client: PurplefishClient,
        agent_room_metadata: AgentRoomMetadata,
        ctx: JobContext,
    ) -> CallScript:
        """Load call script with fallback priority order.

        Attempts to load a call script using the following priority order:
        1. Local file path from input metadata within agent room metadata
        2. Remote script via engagement_id from agent room metadata
        3. Local file path from agent metadata (console mode)

        Args:
            purplefish_client: Client for accessing Purplefish API
            agent_room_metadata: Agent room metadata containing script sources
            ctx: Job context containing agent metadata

        Returns:
            CallScript: The loaded call script

        Raises:
            ValueError: If no call script source is found or available
        """
        # Handle ScreeningAgentRoomMetadata
        if isinstance(agent_room_metadata, ScreeningAgentRoomMetadata):
            # first priority is from engagement_id
            if agent_room_metadata.engagement_id:
                logger.info(
                    "Loading call script from engagement_id",
                    extra={"engagement_id": agent_room_metadata.engagement_id},
                )
                return await self._load_call_script_from_engagement_id(
                    purplefish_client, agent_room_metadata.engagement_id
                )

            # second priority is path from input_metadata
            if agent_room_metadata.input_metadata.internal_call_script_local_path:
                logger.info(
                    "Loading call script from input metadata local path",
                    extra={
                        "path": agent_room_metadata.input_metadata.internal_call_script_local_path
                    },
                )
                return self.load_from_file(
                    agent_room_metadata.input_metadata.internal_call_script_local_path
                )

        # Handle LocalDevAgentRoomMetadata
        if isinstance(agent_room_metadata, LocalDevAgentRoomMetadata):
            if agent_room_metadata.internal_call_script_local_path:
                logger.info(
                    "Loading call script from local dev metadata",
                    extra={"path": agent_room_metadata.internal_call_script_local_path},
                )
                return self.load_from_file(
                    agent_room_metadata.internal_call_script_local_path
                )

        logger.error("No call script source found in agent room metadata")
        raise ValueError("FATAL: No call script found")

    async def _load_call_script_from_engagement_id(
        self, purplefish_client: PurplefishClient, engagement_id: str
    ) -> CallScript:
        try:
            logger.debug(
                "Loading call script from Purplefish API",
                extra={"engagement_id": engagement_id},
            )
            call_script = await purplefish_client.get_agent_config(engagement_id)
            logger.debug(
                "Call_script loaded", extra={"call_script": call_script.model_dump()}
            )
            logger.info(
                "Successfully loaded call script from Purplefish",
                extra={
                    "engagement_id": engagement_id,
                    "script_id": call_script.id,
                    "task_count": len(call_script.tasks),
                },
            )
            return call_script
        except Exception as e:
            logger.error(
                f"Failed to load call script from Purplefish: {e}",
                extra={"engagement_id": engagement_id},
                exc_info=True,
            )
            raise e

    def load_from_file(self, file_path: str) -> CallScript:
        """Load a call script from JSON file"""
        logger.info(f"Loading call script from file: {file_path}")
        with open(file_path) as f:
            data = json.load(f)
        return self._load_script(data)

    def _load_script(self, script_data: dict[str, Any]) -> CallScript:
        """Load a call script from dictionary data"""
        try:
            script = CallScript(**script_data)
            return script
        except Exception as e:
            logger.error(f"Failed to load script: {e}")
            raise e

